        body: `IN THE ill-ventilated dark passage between the front hall and the dining room, Swaminathan's grandmother lived with all her belongings, which
consisted of an elaborate bed made of five carpets, three bed sheets, and
five pillows, a square box made of jute fibre, and a small wooden box
containing copper coins, cardamoms, cloves, and areca-nut.
After the night meal, with his head on his granny's lap, nestling close to her,
Swaminathan felt very snug and safe in the faint atmosphere of cardamom
and cloves.
'Oh, granny!' he cried ecstatically, 'you don't know what a great fellow
Rajam is.' He told her the story of the first enmity between Rajam and Mani
and the subsequent friendship.
'You know, he has a real police dress,' said Swaminathan.
'Is it? What does he want a police dress for?' asked granny.
'His father is the Police Superintendent. He is the master of every policeman
here.' Granny was impressed. She said that it must be a tremendous office
indeed. She then recounted the days when her husband, Swaminathan's
grandfather, was a powerful Sub-Magistrate, in which office he made the
police force tremble before him, and the fiercest dacoits of the place flee.
Swaminathan waited impatiently for her to finish the story. But she went
on, rambled, confused, mixed up various incidents that took place at
different times.
That will do, granny,' he said ungraciously. 'Let me tell you something
about Rajam. Do you know how many marks he gets in Arithmetic?'
'He gets all the marks, does he, child?' asked granny.
'No, silly. He gets ninety marks out of one hundred.'

'Good. But you must also try and get marks like him. . . You know, Swami,
your grandfather used to frighten the examiners with his answers
sometimes. When he answered a question, he did it in a tenth of the time
that others took to do it. And then, his answers would be so powerful that
his teachers would give him two hundred marks sometimes. .. . When he
passed his F.A. he got such a big medal!
I wore it as a pendant for years till—When did I remove it? Yes, when your
aunt was born. . . . No, it wasn't your aunt. ... It was when your father was
born. ... I remember on the tenth day of confinement. . . . No, no. I was
right.
It was when your aunt was born. Where is that medal now?
I gave it away to your aunt—and she melted it and made four bangles out of
it. The fool! And such flimsy bangles too! I have always maintained that
she is the worst fool in our family. ...'
'Oh, enough, granny! You go on bothering about old unnecessary stories.
Won't you listen to Rajam?'
‘Yes, dear, yes.'
'Granny, when Rajam was a small boy, he killed a tiger.' 'Indeed! The brave
little boy!'
You are saying it just to please me. You don't believe it.'
Swaminathan started the story enthusiastically: Rajam's father was camping
in a forest. He had his son with him. Two tigers came upon them suddenly,
one knocking down the father from behind. The other began chasing Rajam,
who took shelter behind a bush and shot. it dead with his gun. 'Granny, are
you asleep?' Swaminathan asked at the end of the story.
'No, dear, I am listening.'
'Let me see. How many tigers came upon how many?'
'About two tigers on Rajam,' said granny.`,
