        body: `IT WAS Saturday and Rajam had promised to come in the afternoon.
Swaminathan was greatly excited. Where was he to entertain him? Probably
in his own 'room'; but his father often came in to dress and undress. No, he
would be at Court, Swaminathan reminded himself with relief. He cleaned
his table and arranged his books so neatly that his father was surprised and
had a good word to say about it.
Swaminathan went to his grandmother. 'Granny,' he said,
'I have talked to you about Rajam, haven't I?
‘Yes. That boy who is very strong but never passes his examination.'
'No. No. That is Mani.'
'Oh, now I remember, it is a boy who is called the Gram or something, that
witty little boy.'
Swaminathan made a gesture of despair. 'Look here granny, you are again
mistaking the Pea for him. I mean Rajam, who has killed tigers, whose
father is the Police Superintendent, and who is great.'
'Oh,' granny cried, 'that boy, is he coming here? I am so glad.'
'H'm. . . . But I have got to tell you—'
'Will you bring him to me? I want to see him.'
'Let us see,' Swaminathan said vaguely, 'I can't promise. But I have got to
tell you, when he is with me, you must not call me or come to my room.'
'Why so?' asked granny.

'The fact is—you are, well you are too old,' said Swaminathan with brutal
candour. Granny accepted her lot cheerfully.
That he must give his friend something very nice to eat, haunted his mind.
He went to his mother, who was squatting before a cutter with a bundle of
plantain leaves beside her. He sat before her, nervously crushing a piece of
leaf this way and that, and tearing it to minute bits.
'Don't throw all those bits on the floor. I simply can't sweep the floor any
more,' she said.
'Mother, what are you preparing for the afternoon tiffin?'
'Time enough to think of it,' said mother.
'You had better prepare something very nice, something fine and sweet.
Rajam is coming this afternoon. Don't make the sort of coffee that you
usually give me. It must be very good and hot.' He remembered how in
Rajam's house everything was brought to the room by the cook. 'Mother,
would you mind if I don't come here for coffee and tiffin? Can you send it
to my room?' He turned to the cook and said: 'Look here you can't come to
my room in that dhoti. You will have to wear a clean, white dhoti and shirt.'
After a while he said: 'Mother, can you ask father to lend me his room for
just an hour or two?' She said that she could not as she was very busy. Why
could he himself not go and ask?
'Oh, he will give more readily if you ask,' said Swaminathan.
He went to his father and said: 'Father, I want to ask you something.'
Father looked up from the papers over which he was bent.
'Father, I want your room.'
'What for?'
'I have to receive a friend,' Swaminathan replied.`,
