        body: `ONE AFTERNOON three weeks later, Swaminathan stood before Mani's
house and gave a low whistle. Mani joined him. They started for Rajam's
house, speculating on the way what the surprise (which Rajam had said he
would give them if they saw him that afternoon) might be. 'I think,' said Swaminathan, 'Rajam is merely joking. It is merely a trick to
get us to his house.' He was very nearly pushed into a gutter for this doubt. 'Probably he has bought a monkey or something,' Swaminathan ventured
again. Mani was gracious enough to admit that it might be so. They thought
of all possible subjects that might surprise them, and gave up the attempt in
the end. Their thoughts turned to their enemies. 'You know what I am going to do?'
Mani asked. 'I am going to break Somu's waist. I know where he lives. He lives in Kabir Street, behind the market. I have often seen him coming
out at nights to a shop in the market for betel leaves.

I shall first fling a
stone at the municipal lamp and put it out. You have no idea how dark
Kabir Street is. ... I shall wait with my club, and as soon as he appears— He
will sprawl in the dust with broken bones. . . .' Swaminathan shuddered at
the thought. 'And that is not all,' said Mani, 'I am going to get that Pea under
by heel and press him to the earth. And Sankar is going to hang by his tuft
over Sarayu, from a peepul branch... .'
They stopped talking when they reached Rajam's house. The gate was
bolted, and they got up the wall and jumped in. A servant came running
towards them. He asked, 'Why, did you climb the wall?' ;
'Is the wall your property?' Mani asked and burst into laughter. 'But if you had broken your ribs—' the servant began.`,
