        minReadSeconds: 120,
        body: `. . . The company was greatly impressed. Rajam then invited everyone to come
forward and say that they would have no more enemies. If Sankar said it, he
would get a bound note-book; if Swaminathan said it, he would get a clock work engine; if Somu said it, he would get a belt; and if Mani said it, he
would get a nice pocket-knife; and the Pea would get a marvellous little
pen. He threw open the cupboard and displayed the prizes. There was silence for
some time as each sat gnawing his nails. Rajam was sweating with his
peace-making efforts. The Pea was the first to rise. He stood before the cup board and said, 'Let me see the fountain-pen.' Rajam gave it him. The Pea turned it round and round and gave it back without any comment.

'Why don't you like it?' Rajam asked. The Pea kept staring into the
cupboard and said, 'Can I have that box?' He pointed at a tiny box with a lot
of yellow and black designs on it and a miniature Taj Mahal on its lid. Rajam said, 'I can't give you that. I want it.' He paused.

He had two more boxes like that in his trunk. He changed his mind,
'No. I don't want it. You can take the box if you like.'
In a short while, Mani was sharpening a knife on his palm; Somu was trying
a belt on; Sankar was fingering a thick bound note-book; and Swaminathan
was jealously clasping a green engine to his bosom.`,
