        id: 2,
        title: 'Rising Action',
        minReadSeconds: 120,
        body: `The Tamil Pundit, with his unshaven face and the silver-rimmed spectacles
set askew on his nose, was guiding the class through the intricacies of Tamil
Grammar. The guide was more enthusiastic than his followers. A continual
buzz filled the air. Boys had formed themselves into small groups and
carried on private conversations. The Pundit made faint attempts to silence
the class by rapping his palms on the table. After a while, he gave up the
attempt and went on with his lecture. His voice was scarcely audible. Sankar and a few others sat on the first bench with cocked-up ears and busy
pencils. Swaminathan and the Pea sat on the last bench.

‘I say, Pea,' said Swaminathan, I got a new brother this morning.'
The Pea was interested. 'How do you like him?' 'Oh, like him! He is hardly
anything. Such a funny looking creature!' said Swaminathan and gave what
he thought was an imitation of his little brother: he shut his eyes,
compressed his lips, folded his hands on his chest, protruded his tongue,
and tilted his head from side to side. The Pea laughed uncontrollably. 'But,'
Swaminathan said, 'this thing has a wonderful pair of hands, so small and
plump, you know! But I tell you, his face is awful, red, red like chilly.'
They listened to the teacher's lecture for a few minutes. 'I say, Swami,'
said the Pea, 'these things grow up soon. I have seen a baby that was just
what your brother is. But you know, when I saw it again during Michaelmas
I could hardly recognise it.'`,
