        body: `'Why do you want money now?' granny asked.
'If you have what I want, have the goodness to oblige me. If not, why ask
futile questions?'
Granny cried to mother: 'If you have money, give this boy six pies.'
But nobody was prepared to oblige Swaminathan. Father dismissed the
request in a fraction of a second, which made Swaminathan wonder what he
did with all the money that he took from his clients.
He now tried a last desperate chance. He fell on his hands and knees, and
resting his cheek on the cold cement floor, peered into the dark space under
his father's heavy wardrobe. He had a wild notion that he might find a few
coins scattered there. He thrust his hand under the wardrobe and moved it in
all directions. All that he was able to collect was a disused envelope musty
with cobweb and dust, a cockroach, and pinches of fine dust.
He sometimes believed that he could perform magic, if only he set about it
with sufficient earnestness. He also remembered Ebenezar's saying in the
class that God would readily help those that prayed to him. He secured a
small cardboard box, placed in it a couple of pebbles, and covered them
with fine sand and leaves. He carried the box to the pooja room and placed
it in a corner. It was a small room in which a few framed pictures of Gods
hung in the wall, and a few bronze and brass idols kept staring at
Swaminathan from a small carved wooden pedestal. A permanent smell of
flowers, camphor, and incense, hung in the air.
Swaminathan stood before the Gods and with great piety informed them of
the box and its contents, how he expected them to convert the two pebbles
into two three-pie coins, and why he needed money so urgently. He
promised that if the Gods helped him; he would give up biting his thumb.
He closed his eyes and muttered: 'Oh, Sri Rama! Thou hast slain Ravana
though he had ten heads, can't you give me six pies? ... If I give you the six
pies now, when will you give me the hoop? I wish you would tell me what
that herb is. ... Mani, shall I tell you the secret of getting a hoop?

Oh, Rama! Give me six pies and I will give up biting my thumb for a year.
.. .'
He wandered aimlessly in the backyard persuading himself that in a few
minutes he could return to the pooja room and take his money—
transmuted pebbles. He fixed a time limit of half an hour.
Ten minutes later he entered the pooja room, prostrated himself before the
Gods, rose, and snatching his box, ran to a secluded place in the backyard.
With a fluttering heart he opened the box. He emptied it on the ground, ran
his fingers through the mass of sand and leaves, and picked up the two
pebbles. As he gazed at the cardboard box, the scattered leaves, sand, and
the unconverted pebbles, he was filled with rage. The indifference of the
Gods infuriated him and brought tears to his eyes. He wanted to abuse the
Gods, but was afraid to. Instead, he vented all his rage on the cardboard
box, and kicked it from place to place and stamped upon the leaves and
sand. He paused and doubted if the Gods would approve of even this. He
was afraid that it might offend them. He might get on without money, but it
was dangerous to incur the wrath of Gods; they might make him fail in his
examinations, or kill father, mother, granny, or the baby. He picked up the
box again and put back into it the sand, the leaves, and the pebbles, that
were crushed, crumpled, and kicked, a minute ago. He dug a small pit at the
root of a banana tree and buried the box reverently.
Ten minutes later he stood in Abu lane, before Mani's house, and whistled
twice or thrice. Mani did not appear. Swaminathan climbed the steps and
knocked on the door. As the door-chain clanked inside, he stood in
suspense. He was afraid he might not be able to explain his presence if
anyone other than Mani should open the door. The door opened, and his
heart sank. A big man with bushy eyebrows stood before him. 'Who are
you?' he asked.
'Who are you? Where is Mani?' Swaminathan asked. This was intended to
convey that he had come to see Mani but was quite surprised to meet this
other person, and would like to know who it was, whom he had the pleasure
of seeing before him. But in his confusion, he could not put this sentiment
in better form.`,
