        body: `The cart driver jabbered: 'Please, sirs, let me—I have to be there.'
'Shut up,' Rajam commanded.
Swaminathan examined the animal and said: 'Come here.'
The cart driver was loath to get down. Mani dragged him from his seat and
gave him a push towards Swaminathan. Swaminathan scowled at him, and
pointing at the sides of the animal, asked: 'Why have you not washed the
animal, you blockhead?'
The villager replied timidly: 'I have washed the animal, sir.
'But why is this here?' Swaminathan asked, pointing at a brown patch.
'Oh, that! The animal has had it since its birth, sir.'
'Birth? Are you trying to teach me?' Swaminathan shouted and raised his
leg to kick the cart driver.
They showed signs of relenting.
'Give the rascal a pass, and be done with him,' Rajam conceded graciously.
Swaminathan took out a pencil stub and a grubby pocket-book that he
always carried about him on principle. It was his habit to note down all
sorts of things: the number of cycles that passed him, the number of people
going barefoot, the number going with sandals or shoes on, and so forth.
He held the paper and pencil ready. Mani took hold of the rope of the
bullock, pushed it back, and turned it the other way round. The cart driver
protested. But Mani said:
'Don't worry. It has got to stand here. This is the boundary.'
'I have to go this way, sir.'
'You can turn it round and go.'
What is your name?' asked Rajam.

'Karuppan,' answered the boy.
Swaminathan took it down.
'I don't know, sir.'
'You don't know? Swami, write a hundred,' said Rajaro
'No sir, no sir, I am not a hundred.'
'Mind your business and hold your tongue. You are a hundred. I will kill
you if you say no. What is your bullock's name?'
'I don't know, sir.’
‘Swami write "Karuppan" again.’
'Sir, that is my name, not the bullock's.'
They ignored this and Swaminathan wrote 'Karuppan' against the name of
the bullock.
'Where are you going?'
'Sethur.'
Swaminathan wrote it down.
'How long will you stay there?'
'It is my place, sir.'
'If that is so, what brought you here?'
'Our headman sent ten bags of coco-nut to the Railway Shed.'
Swaminathan entered every word in his note-book. Then all the three
signed the page, tore it off, gave it to the cart driver, and permitted him to
start.

Much to Swaminathan's displeasure, his father's courts closed in the second
week of May, and father began to spend the afternoons at home.
Swaminathan feared that it might interfere with his afternoon rambles with
Rajam and Mani. And it did. On the very third day of his vacation, father
commanded Swaminathan, just as he was stepping out of the house:
'Swami, come here.'
Father was standing in the small courtyard, wearing a dhoti and a banian,
the dress, which, for its very homeliness, Swaminathan detested to see him
in; it indicated that he did not intend going out in the near future.
'Where are you going?'
'Nowhere.'
Where were you yesterday at this time?'
'Here.'
"You are lying. You were not here yesterday. And you are not going out
now.'
'That is right,' mother added, just appearing from some where, 'there is no
limit to his loafing in the sun. He will die of sunstroke if he keeps on like
this.'
Father would have gone on even without mother's encouragement. But now
her words spurred him to action. Swaminathan was asked to follow him to
his 'room' in his father's dressing-room.
'How many days is it since you have touched your books?' father asked as
he blew off the fine layer of dust on Swaminathan's books, and cleared the
web that an industrious spider was weaving between a corner of the table
and the pile of books.
Swaminathan viewed this question as a gross breach of promise.
'Should I read even when I have no school?'`,
