        id: 3,
        title: 'The Plot Thickens',
        minReadSeconds: 233,
        body: `'Do you think you have passed the B.A.?' father asked.
'I mean, father, when the school is closed, when there is no examination,
even then should I read?'
'What a question! You must read.'
'But, father, you said before the examinations that I needn't read after they
were over. Even Rajam does not read.'
As he uttered the last sentence, he tried to believe it; he clearly remembered
Rajam's complaining bitterly of a home tutor who came and pestered him
for two hours a day thrice a week. Father was apparently deaf to
Swaminathan's remarks. He stood over Swaminathan and set him to dust his
books and clean his table. Swaminathan vigorously started blowing off the
dust from the book covers. He caught the spider carefully, and took it to the
window to throw it out. He held it outside the window and watched it for a
while. It was swinging from a strand that gleamed in a hundred delicate
tints.
'Look sharp! Do you want a whole day to throw out the spider?' father
asked. Swaminathan suddenly realised that he might have the spider as his
pet and that it would be a criminal waste to throw it out. He secretly slipped
it into his pocket and, after shaking an empty hand outside the window ,
returned to his duty at the desk.
'Look at the way you have kept your English Text! Are you not ashamed of
yourself?' Swaminathan picked up the oily red-bound Fourth Reader,
opened it, and banged together the covers, in order to shake off the dust,
and then robbed violently the oily covers with his palm.
'Get a piece of cloth, boy. That is not the way to clean things. Get a piece of
cloth, Swami,' father said, half kindly and half impatiently.
Swaminathan looked about and complained, 'I can't find any here, father.'
'Run and see.'

This was a welcome suggestion. Swaminathan hurried out. He first went to
his grandmother.
'Granny, get me a piece of cloth, quick.'
Where am I to go for a piece of cloth?'
'Where am I to go?' he asked peevishly and added quite irrelevantly,
'if one has got to read even during holidays, I don't see why holidays are
given at all.' 'What is the matter?'
This was his opportunity to earn some sympathy. He almost wept as he
said: 'I don't know what Rajam and Mani will think, waiting for me there, if
I keep on fooling here. Granny, if father cannot find any work to do, why
shouldn't he go and sleep?'
Father shouted across the hall: 'Did you find the cloth?'
Swaminathan answered: 'Granny hasn't got it. I shall see if mother has.' His
mother was sitting in the back corridor on a mat, with the baby sleeping on
her lap. Swaminathan glared at her. Her advice to her husband a few
minutes ago rankled in his heart. 'You are a fine lady, mother,' he said in an
undertone, 'why don't you leave us, poor folk, alone?'
'What?' she asked, unconscious of the sarcasm, and having forgotten what
she had said to her husband a few minutes ago.
'You needn't have gone and carried tales against me. I don't know what I
have done to you.' He would have enjoyed prolonging this talk, but father
was waiting for the duster.
'Can you give me a piece of cloth?' he asked, coming to business.
'What cloth?'
'What cloth! How should I know? It seems I have got to tidy up those—
those books of mine. A fine way of spending the holidays!'`,
