        body: `'Swami, I am glad you know so much about the Rolls Royce. I am at the
same time ashamed to find you knowing so little about Willard Junior.
We had about a dozen Willard Juniors when I was in Bishop Waller's. Oh!
what bats! There are actual springs inside the bat, so that when you touch
the ball it flies. There is fine silk cord wound round the handle. You don't
know anything, and yet you talk! Show me another bat which has silk cord
and springs like the Willard.'
There was a pause, and after that Rajam said, 'Note it down, Swami.'
Swaminathan noted down on a paper, Vilord June-ear bat.' And looking up
asked, 'How many?'
'Say three. Will that do, Mani?'
'Why waste money on three bats? Two will do. . . .'
'But suppose one breaks in the middle of a match?' Rajam asked.
'Do you suppose we are going to supply bats to our opponents? They will
have to come provided with bats. We must make it clear.'
'Even then, if our bat breaks we may have to stop playing.'
'Two will do, Rajam, unless you want to waste money.'
Rajam's enthusiasm was great. He left his chair and sat on the arm of Mani's
chair, gloating over the pictures of cricket goods in the catalogue.
Swaminathan, though he was considered to be bit of a heretic, caught the
enthusiasm and perched on the other arm of the chair. All the three
devoured with their eyes the glossy pictures of cricket balls, bats, and nets.
In about an hour they selected from the catalogue their team's requirements.
And then came the most difficult part of the whole affair—a letter to Messrs
Binns, ordering goods. Bare courtesy made Rajam offer the authorship of
the letter to Mani, who declined it. Swaminathan was forced to accept it in

spite of his protests, and he sat for a long time chewing his pencil without
producing a word: he had infinite trouble with spelling, and the more he
tried to be correct the more muddled he was becoming; in the end he sat so
long thinking of spelling that even such words as 'The' and 'And'
became doubtful. Rajam took up the task himself. Half an hour later he
placed on the table a letter:
'From
M.C.C. (And Victory Union Eleven),
Malgudi.
To
Messrs Binns,
Sportsmen,
Mount Road,
Madras.
'DEAR SIR,
'Please send to our team two junior willard bats, six balls, wickets and other
things quick. It is very urgent. We shall send you money afterwards.
Don't fear. Please be urgent.
'Yours obediently,
'CAPTAIN RAJAM (Captain).'
This letter received Swaminathan's benedictions. But Mani expressed
certain doubts. He wanted to know whether 'Dear' could stand at the
beginning of a letter to a perfect stranger. 'How can you call Binns "Dear
Sir"? You must say "Sir".'

Rajam's explanation was: 'I won't say "Sir". It is said only by clerks. I am
not Binns's clerk. I don't care to address him as "Sir".'
So this letter went as it was. After this exacting work they were resting,
with a feeling of relief, when the postman came in with a card for Rajam.
Rajam read it and cried, 'Guess who has written this?'
'Binns.'
'Silly. It must be our Head Master.'
'Somebody.'
'J. B. Hobbs.'
'It is from Sankar,' Rajam announced joyfully.
'Sankar! We had almost forgotten that old thief.' Swaminathan and Mani
tore the card from Rajam's hand and read:
'MY DEAR FRIEND,
'I am studying here because my father came here. My mother is also here.
All of us are here. And we will be only here. I am doing well. I hope you
are doing well. It is very hot here. I had fever for three days and drank
medicine. I hope I will read well and pass the examination. Is Swami and
Mani doing well! It is very hot here. I am playing cricket now. I can't write
more.
'With regards’,
'Your dearest friend,
'SANKAR.'
'P.S. Don't forget me.
'S.'`,
