        id: 4,
        title: 'Complications',
        minReadSeconds: 238,
        body: `'Indeed! I never knew mother was a sportswoman. Mother, I hope Swami
has filled you with cricket-wisdom.'
Granny said, 'Don't tease the boy. The child is so fond of me. Poor thing!
He has been trying to tell me all sorts of things. You are not in the habit of
explaining things to me. You are all big men. . . .'
Father replied, pointing at the baby, 'Just wait a few days and this little
fellow will teach you all the philosophy and the politics in the world.' He
gently clouted the baby's fat cheeks, and the baby gurgled and chirped
joyfully. 'He has already started lecturing. Listen attentively, mother.'
Granny held up her arms for the baby. But father clung to him tight and
said,
'No. No. I came home early only for this fellow's sake. I can't. Come on,
Swami, I think we had better sit down for food. Where is your mother?'
The captain sternly disapproved of Swaminathan's ways. 'Swami, I must
warn you. You are neglecting the game. You are not having any practice at
all.'
'It is this wretched Board School work.'
'Who asked you to go and join it. They never came and invited you.
Never mind. But let me tell you. Even Bradman, Tate, and everybody
spends four to five hours on the pitch every day, practising, practising. Do
you think you are greater than they?'
'Captain, listen to me. I do my best to arrive at the field before five.
But this wretched Board High School time-table is peculiar.'
A way out had to be found. The captain suggested, 'You must see your Head
Master and ask him to exempt you from extra work till the match is over.' It
was more easily said than done, and Swaminathan said so, conjuring up
before his mind a picture of the wizened face and the small dingy spectacles
of his Head Master.

'I am afraid to ask that monster,' Swaminathan said. 'He may detain me in
Second Form for ages.'
'Indeed! Are you telling me that you are in such terror of your Head
Master? Suppose I see him?'
'Oh, please don't, captain. I beg you. You don't know what a vicious being
he is. He may not treat you well. Even if he behaves well before you, he is
sure to lull me when you are gone.'
'What is the matter with you, Swami? Your head is full of nonsense.
How are we to go on? It is two months since we started the team, and you
have not played even for ten days... .'
Mani, who had stretched himself on the compound wall, now broke in: 'Let
us see what your Head Master can do. Let him say yes or no. If he kills you
I will pulp him. My clubs have had no work for a long time.'
There was no stopping Rajam. The next day he insisted that he would see
the Head Master at the school. He would not mind losing a couple of
periods of his own class. Mani offered to go with him but was advised to
mind his business.
Next morning at nine-thirty Swaminathan spent five minutes rubbing his
eyes red, and then complained of headache. His father felt his temples and
said that he would be all right if he dashed a little cold water on his
forehead.
'Yes, father,' Swaminathan said and went out. He stood outside father's
room and decided that if cold water was a cure for headache he would avoid
it, since he was praying for that malady just then. Rajam was coming to see
the Head Master, and it would be unwise to go to the school that morning.
He went in and asked, 'Father, did you say cold water?'
'Yes.'`,
