        id: 5,
        title: 'Turning Point',
        minReadSeconds: 238,
        body: `'But don't you think it will give me pneumonia or something? I am also
feeling feverish.'
Father felt his pulse and said, 'Now run to school and you will be all right.'
It was easier to squeeze milk out of a stone than to get permission from
father to keep away from school.
He whispered into his granny's ear, 'Granny, even if I die, I am sure father
will insist on sending my corpse to the school.' Granny protested
vehemently against this sentiment.
'Granny, a terrible fever is raging within me and my head is splitting with
headache. But yet, I mustn't keep away from school.'
Granny said, 'Don't go to school.' She then called mother and said,
'This child has fever. Why should he go to school?'
'Has he?' mother asked anxiously, and fussed over him. She felt his body
and said that he certainly had a temperature. Swaminathan said pathetically,
'Give me milk or something, mother. It is getting late for school.' Mother
vetoed this virtuous proposal. Swaminathan faintly said, 'But father may not
like it.' She asked him to lie down on a bed and hurried along to father's
room. She stepped into the room with the declaration, 'Swami has fever, and
he can't go to school.'
'Did you take his temperature?'
'Not yet. It doesn't matter if he misses the school for a day.'
'Anyway, take his temperature,' he said. He feared that his wife might detect
the sarcasm in his suggestion, and added as a palliative, 'that we may know
whether a doctor is necessary.'
A thermometer stuck out of Swaminathan's mouth for half a minute and
indicated normal. Mother looked at it and thrust it back into his mouth.
It again showed normal. She took it to father, and he said, 'Well, it is
normal,' itching to add, 'I knew it.' Mother insisted, 'Something has gone

wrong with the thermometer. The boy has fever. There is no better
thermometer than my hand. I can swear that he has 100.2 now.'
'Quite likely’, father said.
And Swaminathan, when he ought to have been at school, was lying
peacefully, with closed eyes, on his bed. He heard a footstep near his bed
and opened his eyes. Father stood over him and said in an undertone, 'You
are a lucky fellow. What a lot of champions you have in this house when
you don't want to go to school!' Swaminathan felt that this was a sudden
and unprovoked attack from behind. He shut his eyes and turned towards
the wall with a feeble groan.
By the afternoon he was already bedsore. He dreaded the prospect of
staying in bed through the evening. Moreover, Rajam would have already
come to the school in the morning and gone.
He went to his mother and informed her that he was starting for the school.
There was a violent protest at once. She felt him all over and said that he
was certainly better but in no condition to go to school. Swaminathan said,
'I am feeling quite fit, mother. Don't get fussy.'
On the way to the school he met Rajam and Mani. Mani had his club under
his arm. Swaminathan feared that these two had done something serious.
Rajam said, 'You are a fine fellow! Where were you this morning?'
'Did you see the Head Master, Rajam?'
'Not yet. I found that you had not come, and did not see him. I want you to
be with me when I see him. After all it is your business.'
When Swaminathan emerged from the emotional chaos which followed
Rajam's words, he asked, 'What is Mani doing here?'
'I don't know,' Rajam said, 'I found him outside your school with his club,
when he ought to have been in his class.'
'Mani, what about your class?'`,
