        body: `'It is all right,' Mani replied, 'I didn't attend it today.'
'And why your club?' Swaminathan asked.
'Oh! I simply brought it along.'
Rajam asked, 'Weren't you told yesterday to attend your class and mind
your business?'
'I don't remember. You asked me to mind my business only when I offered
to accompany you. I am not accompanying you. I just came this way, and
you have also come this way. This is a public road.' Mani's jest was lost on
them. Their minds were too busy with plans for the impending interview.
'Don't worry, young men,' Mani said, 'I shall see you through your troubles.
I will talk to the Head Master, if you like.'
'If you step into his room, he will call the police,' Swaminathan said.
When they reached the school, Mani was asked to go away, or at worst wait
in the road. Rajam went in, and Swaminathan was compelled to accompany
him to the Head Master's room.
The Head Master was sleeping with his head between his hands and his
elbows resting on the table. It was a small stuffy room with only one
window opening on the weather beaten side-wall of a shop; it was cluttered
with dust-laden rolls of maps, globes, and geometrical squares. The Head
Master's white cane lay on the table across two ink-bottles and some pads.
The sun came in a hot dusty beam and fell on the Head Master's nose and
the table. He was gently snoring. This was a possibility that Rajam had not
thought of.
‘What shall we do?' Swaminathan asked in a rasping whisper.
‘Wait,' Rajam ordered.
They waited for ten minutes and then began to make gentle noises with
their feet. The Head Master opened his eyes and without taking his head
from his hands, kept staring at them vacantly, without showing any sign of

recognition. He rubbed his eyes, raised his eyebrows three times, yawned,
and asked in a voice thick with sleep, 'Have you fellows no class?' He
fumbled for his spectacles and put them on. Now the picture was complete
—wizened face and dingy spectacles calculated to strike terror into the
hearts of Swaminathan. He asked again, 'To what class do you fellows
belong? Have you no class?'
'I don't belong to your school,' Rajam said defiantly.
'Ah, then which heaven do you drop from?'
Rajam said, 'I am the captain of the M.C.C. and have come to see you on
business.'
‘What is that?'
'This is my friend W. S. Swaminathan of Second C studying in your
school....'
'I am honoured to meet you,' said the Head Master turning to Swaminathan.
Rajam felt at that moment that he had found out where the Board High
School got its reputation from.
"I am the captain of the M.C.C.'
'Equally honoured. . .’
'He is in my team. He is a good bowler. . . .'
'Are you?' said the Head Master, turning to Swaminathan.
'May I come to the point?' Rajam asked.
'Do, do,' said the Head Master, 'for heaven's sake, do.'
'It is this,' Rajam said, 'he is a good bowler and he needs some practice. He
can't come to the field early enough because he is kept in the school every
day after four-thirty. What do you want me to do?'

'Sir, can't you permit him to go home after four-thirty?'
The Head Master sank back in his chair and remained silent.
Rajam asked again, What do you say, sir, won't you do it?'
'Are you the Head Master of this school or am I?'
'Of course you are the Head Master, sir. In Albert Mission they don't keep
us a minute longer than four-thirty. And we are exempted from drill if we
play games.'
'Here I am not prepared to listen to your rhapsodies on that pariah school.
Get out.'
Mani, who had been waiting outside, finding his friends gone too long, and
having his own fears, now came into the Head Master's room.
‘Who is this?' asked the Head Master, looking at Mani sourly. ‘What do you
want?'
'Nothing,' Mani replied and quietly stood in a corner.
'I can't understand why every fellow who finds nothing to do comes and
stands in my room.'
'I am the Police Superintendent's son,' Rajam said abruptly.
'Is that so? Find out from your father what he was doing on the day a gang
of little rascals came in and smashed these windows. . .. What is the thing
that fellow has in his hand?'
'My wooden club,' Mani answered.
Rajam added, 'He breaks skulls with it. Come out, Mani, come on, Swami.
There is nothing doing with this—this mad- cap.'`,
