        body: `IT was three-thirty on Sunday afternoon. The match between the M.C.C.
and the Y.M.U. was still in progress. The Y.M.U. had won the toss, and
were all out for eighty-six at two o'clock. The captain's was the top score,
thirty-two. The M.C.C. had none to bowl him out, and he stood there like an
automaton, hitting right and left, tiring out all the bowlers.
He kept on for hours, and the next batsman was as formidable, though not a
scorer. He exhausted the M.C.C. of the little strength that was left, and
Rajam felt keenly the lack of a clever bowler.
After the interval the game started again at two-thirty, and for the hour that
the M.C.C. batted the score stood at the unimpressive figure of eight with
three out in quick succession. Rajam and Mani had not batted. Rajam
watched the game with the blackest heart and cursed heartily everybody
concerned. The match would positively close at five-thirty; just two hours
more, and would the remaining eight make up at least seventy-eight and
draw the match? It was a remote possibility. In his despair he felt that at
least six more would follow suit without raising the score even to twenty.
And then he and Mani would be left. And he had a wild momentary hope
that each might be able to get forty with a few judicious sixers and
boundaries.
He was squatting along with his players on the ground in the shade of the
compound wall.
'Raju, a minute, come here,', came a voice from above.
Rajam looked up and saw his father's head over the wall.
'Father, is it very urgent?'
'It is. I won't detain you for more than a minute.'`,
