        body: `'Oh, Swami. I am so glad to see you alive. I was—I was very much troubled
about you. Where were you all along?'
'I—I—I really can't say. I don't know where I was. Some- where—'
He recounted in this style his night of terrors and the subsequent events.
'Have I not always said that you were the worst coward I have ever known?
You would have got safely back home if you had kept your head cool and
followed the straight road.
‘You imagined all sorts of things.'
Swaminathan took this submissively and said, 'But I can't believe that I was
picked up by that cart-man. I don't remember it at all.'
Mani advised, 'If he happens to come to your place during Deepavali or
Pongal festival, don't behave like a niggard. He deserves a bag of gold. If he
had not cared to pic k you up, you might have been eaten by a tiger.'
'And I have done another nasty thing,' Swaminathan said, 'I didn't thank and
say "Good-bye" to the Forest Officer before I came away. He was standing
near the car all the time.' 'If he was so near why did you seal your mouth'?'
'I didn't think of it till the car had come half-way.'
'You are a—a very careless fellow. You ought to have thanked him.'
'Now what shall I do? Shall I write to him?'
'Do. But do you know his address?'
'My father probably does.'
'What will you write?'
'Just tell him—I don't know. I shall have to ask father about it. Some nice
letter, you know. I owe him so much for bringing me back in time for the
match.'

'What are you saying?' Mani asked.
'Are you deaf? I was saying that I must ask father to write a nice letter, that
is all.'
'Not that. I heard something about the match. What is it?'
'Yes?'
'Are you mad to think that you are in time for the match?' asked Mani.
He then related to Swaminathan the day's encounter with the Y.M.U. and
the depressing results, liberally explaining what Swaminathan's share was
in the collapse of the M.C.C.
'Why did you have it to-day?' Swaminathan asked weakly.
‘Why not?'
'But this is only Saturday.'
'Who said that?'
‘The Forest Officer said that this was only Saturday.’
'You may go and tell him that he is a blockhead,' Mani retorted.
Swaminathan persisted that it could not be Sunday, till Mani threatened to
throw him down, sit on his body, and press his entrails out.
Swaminathan remained in silence, and then said, 'I won't write him that
letter. He has deceived me.'
'Who?'
'The Forest Officer. . . . And what does Rajam say about me?'
'Rajam says a lot, which I don't wish to repeat. But I will tell you one thing.
Never appear before him. He will never speak to yo u. He may even shoot

you on sight.'
'What have I done?' asked Swaminathan.
'You have ruined the M.C.C. You need not have promised us, if you had
wanted to funk. At least you could have told us you were going away.
Why did you hide it from Rajam when you saw him at our school? That is
what Rajam wants to know.'
Swaminathan quietly wept, and begged Mani to pacify Rajam and convey
to him Swaminathan's love and explanations. Mani refused to interfere,
'You don't know Rajam. He is a gem. But it is difficult to get on with him.'
With a forced optimism in his tone Swaminathan said,
'He will be all right when he sees me. I shall see him tomorrow morning.'
Mani wanted to change the topic, and asked: 'Are you going back to
school?'
'Yes, next week. My father has already seen the Head Master, and it seems
things will be all right in the school. He seems to have known everything
about the Board School business.'
‘Yes, I and Rajam told him everything.'
'After all, I shall have to go back to the Board High School. Father says I
can't change my school now.'`,
