        body: `ON Tuesday morning, ten days later, Swaminathan rose from bed with a
great effort of will at five o'clock. There was still an hour for the train to
arrive at the Malgudi Station and leave it four minutes later, carrying away
Rajam, for ever. Swaminathan had not known that this was to happen till Mani came and
told him, on the previous night at about ten, that Rajam's father was
transferred -to Trichinopoly and the whole family would be leaving
Malgudi on the following morning. Mani said that he had known it for
about a week, but Rajam had strictly forbidden him to say anything about it
to Swaminathan. But at the last moment Mani could not contain himself and
had violated Rajam's ban. A great sense of desolation seized Swaminathan at once. The world seemed
to have become blank all of a sudden. The thought of Lawley Extension
without Rajam appalled him with its emptiness. He swore that he would
never go there again. He raved at Mani. And Mani bore it patiently. Swaminathan could not think of a world without Rajam.

What was he to do
in the evenings? How was he to spend the holiday afternoons? Whom was
he to think of as his friend? At the same time he was filled with a sense of guilt: he had not gone and
seen Rajam even once after his return. Fear, shame, a feeling of uncertainty,
had made him postpone his visit to Rajam day after day. Twice he had gone
up to the gate of Rajam's house, but had turned back, his courage and
determination giving way at the last moment. He was in this state, hoping to
see Rajam every to-morrow, when Mani came to him with the shattering
news. Swaminathan wanted to rush up to Rajam's house that very second
and claim him once again. But—but—he felt awkward and shirked. Tomorrow morning at the station. The train was leaving at six. He would go
to the station at five.`,
